// ---------- the request ----------

/** A Gmail message or conversation id, as Gmail writes them: letters and digits. Anything else is never sent to Gmail. */
const GMAIL_ID = /^[A-Za-z0-9_-]{1,64}$/
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i
const PAGE_TOKEN = /^[A-Za-z0-9_-]{1,256}$/

/** The longest search the tab may send. */
export const MY_MAIL_QUERY_MAX = 500

const VIEWS: readonly MyMailView[] = ['toTag', 'tagged', 'all']
const LABELS: readonly MyMailLabel[] = ['INBOX', 'SENT']
const JOB_KINDS: readonly MyMailJobKind[] = ['bid', 'project', 'pipeline']

/**
 * A request as the tab posts it (`MyMailRequest`), read strictly, or null and the function answers `badRequest`. A list
 * with no view reads as To tag; its search is trimmed; its labels are Gmail's INBOX and SENT alone, once each, both when
 * none are named. A job's id is a uuid, kept lower-case so it keys as the database keys it.
 */
export function parseMyMailRequest(raw: unknown): MyMailRequest | null {
  if (!raw || typeof raw !== 'object') return null
  const r = raw as Record<string, unknown>
  switch (r.action) {
    case 'list': {
      const view = r.view === undefined || r.view === null ? 'toTag' : VIEWS.find((v) => v === r.view)
      if (!view) return null
      if (r.q !== undefined && r.q !== null && typeof r.q !== 'string') return null
      const q = typeof r.q === 'string' ? r.q.trim() : ''
      if (q.length > MY_MAIL_QUERY_MAX) return null
      const token = r.pageToken
      if (token !== undefined && token !== null && (typeof token !== 'string' || !PAGE_TOKEN.test(token))) return null
      let labels: MyMailLabel[] = []
      if (r.labels !== undefined && r.labels !== null) {
        if (!Array.isArray(r.labels)) return null
        const picked = r.labels.map((l) => LABELS.find((x) => x === l))
        if (picked.some((l) => !l)) return null
        labels = LABELS.filter((l) => picked.includes(l))
      }
      return { action: 'list', view, ...(q ? { q } : {}), ...(typeof token === 'string' ? { pageToken: token } : {}), ...(labels.length > 0 ? { labels } : {}) }
    }
    case 'open':
      return typeof r.gmailId === 'string' && GMAIL_ID.test(r.gmailId) ? { action: 'open', gmailId: r.gmailId } : null
    case 'tag': {
      if (typeof r.threadId !== 'string' || !GMAIL_ID.test(r.threadId)) return null
      // The seat's door (server 0.30.0): `as` the login whose box it is, `plan` for the dry run. Anything else in them is no request.
      if (r.plan !== undefined && typeof r.plan !== 'boolean') return null
      if (r.as !== undefined && (typeof r.as !== 'string' || !myMailAddressKey(r.as))) return null
      const plan = r.plan === true ? { plan: true as const } : {}
      const as = typeof r.as === 'string' ? r.as.trim().toLowerCase() : null
      // A person in place of the job (punch list #289): the seat's alone, so `as` is required; `stop` lifts the follow.
      if (r.person !== undefined && r.person !== null) {
        if (r.job !== undefined || as === null) return null
        const p = r.person as Record<string, unknown>
        if (typeof p !== 'object' || typeof p.personId !== 'string' || !UUID.test(p.personId)) return null
        if (r.stop !== undefined && typeof r.stop !== 'boolean') return null
        return { action: 'tag', threadId: r.threadId, person: { personId: p.personId.toLowerCase() }, as, ...plan, ...(r.stop === true ? { stop: true } : {}) }
      }
      const job = r.job
      if (!job || typeof job !== 'object') return null
      const j = job as Record<string, unknown>
      const kind = JOB_KINDS.find((k) => k === j.kind)
      if (!kind || typeof j.id !== 'string' || !UUID.test(j.id)) return null
      return { action: 'tag', threadId: r.threadId, job: { kind, id: j.id.toLowerCase() }, ...plan, ...(as ? { as } : {}) }
    }
    case 'untag':
      return typeof r.threadId === 'string' && GMAIL_ID.test(r.threadId) ? { action: 'untag', threadId: r.threadId } : null
    default:
      return null
  }
}

// ---------- the search a page reads ----------

/**
 * The person's own search, fenced: its brackets and braces taken out, and its quotes too when they do not pair, so it can
 * never close the group it sits in and reach past the fence's terms. Wrapped as one group; '' when nothing is left.
 */
export function fencedQuery(q: string): string {
  let s = q.replace(/[(){}]/g, ' ')
  if ((s.match(/"/g) ?? []).length % 2 === 1) s = s.replace(/"/g, ' ')
  s = s.replace(/\s+/g, ' ').trim()
  return s ? `(${s})` : ''
}

/**
 * The Gmail search one page of the list reads: the Inbox and the Sent box, or the one asked for; never Drafts, Spam,
 * Trash or Chats; never a label the person left out (`users.my_mail_hidden_labels`, by name); and the person's own search
 * as one group. No view names a label of the app's: a tag puts none on (v2.7035), so what is tagged is the database's
 * own record alone. Tagged with no search of the person's own never comes here: its page is read from the tagged
 * conversations themselves (`taggedOffset`), so it never fills with mail it hides. With a search it reads as All does
 * and `viewRows` keeps the tagged.
 */
export function myMailQuery(input: { view: MyMailView; labels?: readonly MyMailLabel[]; hidden?: readonly string[]; q?: string }): string {
  const asked = input.labels && input.labels.length > 0 ? LABELS.filter((l) => input.labels!.includes(l)) : LABELS
  const boxes = asked.map((l) => (l === 'INBOX' ? 'in:inbox' : 'in:sent'))
  const parts = [boxes.length > 1 ? `(${boxes.join(' OR ')})` : boxes[0]!, '-in:drafts', '-in:spam', '-in:trash', '-in:chats']
  const seen = new Set<string>()
  for (const name of input.hidden ?? []) {
    const label = name.replace(/"/g, '').replace(/\s+/g, ' ').trim()
    if (!label || seen.has(label.toLowerCase())) continue
    seen.add(label.toLowerCase())
    parts.push(`-label:"${label}"`)
  }
  const own = fencedQuery(input.q ?? '')
  if (own) parts.push(own)
  return parts.join(' ')
}

/** How many tagged conversations a page of Tagged reads, each whole: Gmail counts 10 units a conversation. */
export const MY_MAIL_TAGGED_PAGE = 15

/**
 * Where a page of Tagged starts among the person's tagged conversations, newest mail first: its page token is a count
 * of our own, since the page comes from `email_tag_threads` and never from a Gmail search. Anything else starts at 0.
 */
export function taggedOffset(pageToken: string | null | undefined): number {
  return typeof pageToken === 'string' && /^\d{1,6}$/.test(pageToken) ? Number(pageToken) : 0
}

/** The token of the page after this one, or null when this page came up short of a full one. */
export function taggedNextToken(offset: number, got: number): string | null {
  return got >= MY_MAIL_TAGGED_PAGE ? String(offset + MY_MAIL_TAGGED_PAGE) : null
}

/**
 * Whether a mail of a tagged conversation is in a box the person asked for. Asked for neither or both, every mail of
 * the conversation is, an archived one too: Tagged shows what is on the job, wherever Gmail files it now.
 */
export function inAskedBoxes(labelIds: readonly string[] | undefined, asked: readonly MyMailLabel[] | undefined): boolean {
  if (!asked || asked.length === 0 || LABELS.every((l) => asked.includes(l))) return true
  return (labelIds ?? []).some((l) => asked.some((a) => a === l))
}

/** How many messages a list reads whole at once: Gmail counts 5 units a read and lets a box spend 250 a second. */
export const MY_MAIL_READ_CHUNK = 10

/** A message Gmail files as a draft, in Spam or Trash, or a chat: never read for the tab, never written by a tag. */
export function neverRead(labels: readonly string[] | undefined): boolean {
  return (labels ?? []).some((l) => Object.prototype.hasOwnProperty.call(MY_MAIL_NEVER_LABELS, l))
}

/** The labels a person leaves out as `users.my_mail_hidden_labels` holds them: the names, trimmed, the empty ones dropped. */
export function myMailHiddenLabels(raw: unknown): string[] {
  return Array.isArray(raw) ? raw.flatMap((l) => (typeof l === 'string' && l.trim() ? [l.trim()] : [])) : []
}

/**
 * Gmail's ids of the labels a person leaves out, from their box's labels (`users.labels.list`): each label whose name is
 * one they named, trimmed and case-blind, the name whole. A tag and the follow skip a mail carrying one, so a mail the
 * list never reads is never copied onto a job either. None when they named none.
 */
export function myMailHiddenLabelIds(labels: readonly { id: string; name?: string | null }[] | null | undefined, hidden: readonly string[]): string[] {
  const named = new Set(hidden.map((h) => h.trim().toLowerCase()).filter((h) => h !== ''))
  if (named.size === 0) return []
  return [...new Set((labels ?? []).filter((l) => l.id && named.has((l.name ?? '').trim().toLowerCase())).map((l) => l.id))]
}

/**
 * A mail the tab never shows (v2.6296): a draft, Spam, Trash or a chat (`neverRead`), or a mail under a label the person
 * leaves out (`hidden`, Gmail's ids from `myMailHiddenLabelIds`). The list's search asks Gmail to leave both out by name
 * (`myMailQuery`); this holds by id whatever the search lets past, and keeps `open` from showing one, as the mail asked
 * for or as a row of its conversation, which until v2.6296 it did. The guide promises a label left out is never read.
 */
export function leftOutOfTab(labels: readonly string[] | undefined, hidden: readonly string[]): boolean {
  if (neverRead(labels)) return true
  return hidden.length > 0 && (labels ?? []).some((l) => hidden.includes(l))
}

// ---------- how a refusal answers ----------

/** The HTTP status each refusal answers with (`docs/EDGE_FUNCTIONS.md` → gmail-mine). */
export const MY_MAIL_REFUSAL_STATUS: Readonly<Record<MyMailRefusalError, number>> = {
  signIn: 401,
  readOnly: 403,
  officeOnly: 403,
  off: 403,
  imitated: 403,
  offWorkspace: 403,
  badRequest: 400,
  notFound: 404,
  google: 502,
}

/**
 * The status of a step the database or the bucket refused mid-way. Its refusal is `google`, the one kind that says try
 * again: the contract has no kind of its own for a server's failure, and the tab shows the words as they come.
 */
export const MY_MAIL_STOPPED_STATUS = 500

/** Our words, then who said what after them, ending on a stop. */
function withReason(ours: string, said: string, reason: string): string {
  const r = reason.replace(/\s+/g, ' ').trim()
  return r ? `${ours} ${said}: ${/[.!?]$/.test(r) ? r : `${r}.`}` : ours
}

/** The reasons Google's token exchange gives for an address it will not hand the app. */
const REFUSED_GRANT = /\b(?:unauthorized_client|invalid_grant|access_denied|admin_policy_enforced)\b/i

/**
 * A failed token exchange (`_shared/googleToken.ts` throws `Google token exchange failed (<status>): <reason>`). A 400,
 * 401 or 403, or Google's `unauthorized_client` or `invalid_grant`, is an address the delegation will not read: off the
 * company's Workspace (the dev's own address), or not covered by it. Ours, then Google's reason. Anything else is
 * Google's own failure.
 */
export function tokenRefusal(message: string): MyMailRefusal {
  const m = /Google token exchange failed \((\d{3})\):\s*([\s\S]*)$/.exec(message)
  const status = m ? Number(m[1]) : null
  const reason = (m ? m[2]! : message).trim()
  const kind: MyMailRefusalError = (status !== null && [400, 401, 403].includes(status)) || REFUSED_GRANT.test(reason) ? 'offWorkspace' : 'google'
  return myMailRefusal(kind, withReason(MY_MAIL_REFUSAL_WORDS[kind], m ? 'Google said' : 'The reason', reason))
}

/**
 * A Gmail call that failed (`_shared/gmail.ts`'s `GmailError`, `Gmail <path> failed (<status>): <reason>`): a mail or a
 * conversation Gmail no longer has is `notFound` when the call named one (`missing`); anything else is Google's own
 * failure, ours then Gmail's reason.
 */
export function gmailRefusal(e: { status?: number | null; message: string }, missing = false): MyMailRefusal {
  if (missing && e.status === 404) return myMailRefusal('notFound')
  const m = /failed \((\d{3})\):\s*([\s\S]*)$/.exec(e.message)
  return myMailRefusal('google', withReason(MY_MAIL_REFUSAL_WORDS.google, m ? 'Gmail said' : 'The reason', m ? m[2]! : e.message))
}

/**
 * A step the database or the bucket refused: what stopped, that what was done stays, and the reason, the database's
 * unless `said` names another speaker.
 */
export function stoppedRefusal(what: string, reason: string, said = 'The database said'): MyMailRefusal {
  return myMailRefusal('google', withReason(`${what.trim()} What was done stays. Try again in a minute.`, said, reason))
}

// ---------- the mail, for the reader ----------

/** The most HTML an open answers: a longer body is left to its words (`bodyText`). */
export const MY_MAIL_HTML_MAX = 500_000

const headersOf = (part: GmailPart): Record<string, string> => {
  const out: Record<string, string> = {}
  for (const h of part.headers ?? []) {
    const key = h.name.trim().toLowerCase()
    if (key && !(key in out)) out[key] = h.value
  }
  return out
}

const decodeBytes = (bytes: Uint8Array, charset: string | null): string => {
  try {
    return new TextDecoder(charset || 'utf-8').decode(bytes)
  } catch {
    return new TextDecoder('utf-8').decode(bytes)
  }
}

/**
 * A mail's HTML as it was sent, for the reader to sanitise and draw: each HTML part that is not a file, in order, read by
 * its charset as the bids@ reader's parser reads the words. Null when the mail has none, or more than an open answers.
 */
export function myMailBodyHtml(message: Pick<GmailMessage, 'payload'>): string | null {
  const parts: string[] = []
  const walk = (part: GmailPart) => {
    const mime = (part.mimeType ?? '').toLowerCase()
    if (mime.startsWith('multipart/')) {
      for (const kid of part.parts ?? []) walk(kid)
      return
    }
    const own = headersOf(part)
    if (mime !== 'text/html' || part.filename || /^\s*attachment/i.test(own['content-disposition'] ?? '')) return
    const charset = /charset="?([^";\s]+)"?/i.exec(own['content-type'] ?? '')?.[1] ?? null
    parts.push(decodeBytes(base64UrlBytes(part.body?.data ?? ''), charset))
  }
  if (message.payload) walk(message.payload)
  const html = parts.join('\n').trim()
  return html && html.length <= MY_MAIL_HTML_MAX ? html : null
}

/** A header's addresses as the tab draws them: the name trimmed ('' for none) and the address. */
export function myMailParties(list: readonly EmailAddress[]): MyMailParty[] {
  return list.map((a) => ({ name: a.name?.trim() ?? '', address: a.address.trim() }))
}

/** The files a mail carries, as the row counts them: a small picture placed in the body (a signature's logo) left out. */
export function myMailFileList(email: Pick<EmailIn, 'files'>): MyMailFile[] {
  return email.files.filter((f) => fileKeep(f) !== 'skip').map((f) => ({ name: f.name, mime: f.mime, size: f.size }))
}

// ---------- which jobs are open, and their chips ----------

/** A bid as the guess reads it: its number and name, and its outcome. */
export interface MyMailBidRow extends SubjectBidRow {
  outcome: string | null
}

/** A GC project: its `projects` row's number and name, with its `gc_projects` row's stage and the day it was lost. */
export interface MyMailProjectRow extends SubjectProjectRow {
  stage: string | null
  lost_on: string | null
}

/** A Pipeline job: its numbers, its name, its status, and the customers on it (the billed one and the GC). */
export interface MyMailPipelineRow extends SubjectPipelineRow {
  status: string | null
  customer_id: string | null
  gc_customer_id: string | null
}

/**
 * Whether a job is open, for the guess (`mailGuess.ts`, steps 3 and 4): a job that is not finished. A bid is open while
 * it has no outcome (not won, lost, or started or complete); a GC project while it is not closed and was not lost; a
 * Pipeline job until it is paid, since a billed job still draws mail about its money. Simple on purpose: a guess is only
 * ever offered with a Yes.
 */
export const bidIsOpen = (row: Pick<MyMailBidRow, 'outcome'>): boolean => !(row.outcome ?? '').trim()
export const gcProjectIsOpen = (row: Pick<MyMailProjectRow, 'stage' | 'lost_on'>): boolean => (row.stage ?? '').trim().toLowerCase() !== 'closed' && !row.lost_on
export const pipelineIsOpen = (row: Pick<MyMailPipelineRow, 'status'>): boolean => (row.status ?? '').trim().toLowerCase() !== 'paid'

/** The jobs a page read, by kind: GC projects only (a `projects` row `gc_projects` does not hold is no job here). */
export interface MyMailJobRows {
  bids: readonly MyMailBidRow[]
  projects: readonly MyMailProjectRow[]
  pipeline: readonly MyMailPipelineRow[]
  prefixes: LedgerPrefixMap
}

/** Every job the rows hold as `subjectJobs` lists it (no `mine` yet), its chip, and whether it is open, by key. */
export function myMailJobs(rows: MyMailJobRows): { jobs: SubjectJob[]; chips: Record<string, MyMailJobChip>; open: Record<string, boolean> } {
  const jobs = subjectJobs(rows, new Set())
  const chips: Record<string, MyMailJobChip> = {}
  for (const j of jobs) {
    const chip = subjectJobChip(j)
    if (chip) chips[j.key] = chip
  }
  const open: Record<string, boolean> = {}
  for (const b of rows.bids) open[jobKey({ kind: 'bid', id: b.id })] = bidIsOpen(b)
  for (const p of rows.projects) open[jobKey({ kind: 'project', id: p.id })] = gcProjectIsOpen(p)
  for (const j of rows.pipeline) open[jobKey({ kind: 'pipeline', id: j.id })] = pipelineIsOpen(j)
  return { jobs, chips, open }
}

// ---------- the facts a page's guesses read ----------

/** An address as `contact_channel_key('email', …)` keys it: trimmed and lower-case, '' when it is not one. */
export function myMailAddressKey(address: string | null | undefined): string {
  const a = (address ?? '').trim().toLowerCase()
  return a.includes('@') ? a : ''
}

/** A domain safe to name in a PostgREST filter: letters, digits, dashes and dots, with a dot. */
const SAFE_DOMAIN = /^[a-z0-9](?:[a-z0-9-]*[a-z0-9])?(?:\.[a-z0-9](?:[a-z0-9-]*[a-z0-9])?)+$/

/** Our own domains: the person's, the boxes' and the app's sender's. A domain of ours never names a customer. */
export function myMailOurDomains(addresses: Iterable<string>): Set<string> {
  const out = new Set<string>()
  for (const a of addresses) {
    const d = domainOf(a)
    if (d) out.add(d)
  }
  return out
}

/**
 * What a page's guesses need read: the other parties' addresses (by key), the subjects' numbers (`subjectNumbers`, as the
 * bids@ reader reads them), and the parties' domains worth asking about: never an open mail service's, never ours.
 */
export function myMailGuessAsks(rows: readonly Pick<MyMailRow, 'who' | 'subject'>[], ourDomains: Iterable<string>): { addresses: string[]; numbers: string[]; domains: string[] } {
  const ours = new Set([...ourDomains].map((d) => d.trim().toLowerCase()))
  const addresses = new Set<string>()
  const numbers = new Set<string>()
  const domains = new Set<string>()
  for (const r of rows) {
    const key = myMailAddressKey(r.who.address)
    if (key) addresses.add(key)
    if (r.subject !== MY_MAIL_NO_SUBJECT) for (const n of subjectNumbers(r.subject)) numbers.add(n)
    const d = domainOf(key)
    if (d && SAFE_DOMAIN.test(d) && !OPEN_MAIL_DOMAINS.has(d) && !ours.has(d)) domains.add(d)
  }
  return { addresses: [...addresses], numbers: [...numbers], domains: [...domains] }
}

/** A PostgREST `or` over the columns ending on any of the domains (`<column>.ilike.*@<domain>`), safe domains alone. */
export function domainFilter(columns: readonly string[], domains: readonly string[]): string {
  return domains
    .filter((d) => SAFE_DOMAIN.test(d))
    .flatMap((d) => columns.map((c) => `${c}.ilike.*@${d}`))
    .join(',')
}

/** The contacts each address is on, by its key, from `contact_channels` rows of kind email. */
export function contactsByAddress(rows: readonly { contact_id: string; key?: string | null; value?: string | null }[]): Record<string, string[]> {
  const out: Record<string, string[]> = {}
  for (const r of rows) {
    const key = myMailAddressKey(r.key || r.value)
    if (!key) continue
    const list = (out[key] ??= [])
    if (!list.includes(r.contact_id)) list.push(r.contact_id)
  }
  return out
}

/** Each contact's jobs (`contact_jobs`), by contact id: the job's key and whether it is the contact's star (`is_default`). */
export function contactJobsOf(
  rows: readonly { contact_id: string; bid_id: string | null; project_id: string | null; jobs_ledger_id: string | null; is_default?: boolean | null }[],
): Record<string, { key: string; star: boolean }[]> {
  const out: Record<string, { key: string; star: boolean }[]> = {}
  for (const r of rows) {
    const key = jobKeyOfRow(r)
    if (!key) continue
    const list = (out[r.contact_id] ??= [])
    const had = list.find((t) => t.key === key)
    if (had) had.star = had.star || r.is_default === true
    else list.push({ key, star: r.is_default === true })
  }
  return out
}

/** A customer as the domain step reads it: its name and its own emails. */
export interface MyMailCustomerRow {
  id: string
  name: string | null
  contact_info?: unknown
  billing_email?: string | null
}

/** One of a customer's contact persons, by email. */
export interface MyMailCustomerPersonRow {
  customer_id: string
  email: string | null
}

/**
 * The customers on each domain: one whose own email (`contact_info.email`, `billing_email`) or one of whose contact
 * persons' emails is on it. `customers` holds every customer the persons point at too; one with no name says nothing.
 */
export function domainCustomers(
  domains: readonly string[],
  customers: readonly MyMailCustomerRow[],
  persons: readonly MyMailCustomerPersonRow[],
): Record<string, { customerId: string; name: string }[]> {
  const wanted = new Set(domains)
  const byId = new Map(customers.map((c) => [c.id, c]))
  const out: Record<string, { customerId: string; name: string }[]> = {}
  const add = (address: unknown, customerId: string) => {
    const d = typeof address === 'string' ? domainOf(address) : ''
    const name = byId.get(customerId)?.name?.trim() ?? ''
    if (!d || !wanted.has(d) || !name) return
    const list = (out[d] ??= [])
    if (!list.some((x) => x.customerId === customerId)) list.push({ customerId, name })
  }
  for (const c of customers) {
    const own = c.contact_info && typeof c.contact_info === 'object' ? (c.contact_info as Record<string, unknown>).email : null
    add(own, c.id)
    add(c.billing_email, c.id)
  }
  for (const p of persons) add(p.email, p.customer_id)
  return out
}

/** Each customer's open Pipeline jobs, by key: the jobs it is the billed customer on, or the GC of. */
export function customerOpenJobs(pipeline: readonly MyMailPipelineRow[]): Record<string, string[]> {
  const out: Record<string, string[]> = {}
  for (const j of pipeline) {
    if (!pipelineIsOpen(j)) continue
    const key = jobKey({ kind: 'pipeline', id: j.id })
    for (const c of new Set([j.customer_id, j.gc_customer_id])) {
      if (!c) continue
      const list = (out[c] ??= [])
      if (!list.includes(key)) list.push(key)
    }
  }
  return out
}

/** What one page read for its guesses, the function's reads folded into plain maps. */
export interface MyMailPageFacts {
  /** Every job the page's subjects or parties may name, as `subjectJobs` lists them, `mine` not yet set. */
  jobs: readonly SubjectJob[]
  chips: Readonly<Record<string, MyMailJobChip>>
  open: Readonly<Record<string, boolean>>
  contactsByAddress: Readonly<Record<string, readonly string[]>>
  contactJobs: Readonly<Record<string, readonly { key: string; star: boolean }[]>>
  domainCustomers: Readonly<Record<string, readonly { customerId: string; name: string }[]>>
  customerOpenJobs: Readonly<Record<string, readonly string[]>>
}

/**
 * One row's facts for `guessJob`, from what its page read. The other party's contact is the one their address is on,
 * when it is on one alone: two contacts on one address say nothing about which. Its jobs are the subject's `mine` (the
 * bids@ reader's `jobFor` reads the sender's own jobs the same way) and the party's jobs, each with its star and whether
 * it is open. Each customer on the party's domain gives its one open Pipeline job; a customer with two gives none.
 */
export function myMailGuessFacts(row: Pick<MyMailRow, 'who'>, page: MyMailPageFacts, taggedJob: MyMailJobChip | null = null): MyMailGuessFacts {
  const address = myMailAddressKey(row.who.address)
  const contacts = page.contactsByAddress[address] ?? []
  const contact = contacts.length === 1 ? contacts[0]! : null
  const ties = contact ? (page.contactJobs[contact] ?? []) : []
  const mine = new Set(ties.map((t) => t.key))
  const partyJobs = ties.flatMap((t) => {
    const chip = page.chips[t.key]
    return chip ? [{ chip, star: t.star, open: page.open[t.key] === true }] : []
  })
  const domainJobs = (page.domainCustomers[domainOf(address)] ?? []).flatMap((c) => {
    const keys = page.customerOpenJobs[c.customerId] ?? []
    const chip = keys.length === 1 ? page.chips[keys[0]!] : undefined
    return chip ? [{ chip, customer: c.name }] : []
  })
  return { subjectJobs: page.jobs.map((j) => ({ ...j, mine: mine.has(j.key) })), partyJobs, domainJobs, taggedJob }
}

/** A line as the function reads one: its id and its job, whose box it came from, and who last tied it. */
export interface MyMailLine {
  id: string
  bid_id: string | null
  project_id: string | null
  jobs_ledger_id: string | null
  mail_user_id?: string | null
  tied_by?: string | null
}

/**
 * A row with what the database holds: the tagged conversation's chip with this mail's line on it, the line that holds
 * this mail (the boxes', or an earlier tag's) and its job, and the guess when there is one. A tagged row has no guess.
 */
export function filledRow(row: MyMailRow, held: { tagged: MyMailJobChip | null; line: MyMailLine | null; guess: MyMailGuess | null }, me?: string): MyMailRow {
  // A line this person's own tag wrote is theirs, drawn through `tagged`; `inMessages` names a line someone else holds
  // (the boxes' reader, or another person's tag), the one the tab cannot untag.
  const theirs = held.line && !(me && held.line.mail_user_id === me) ? held.line : null
  return {
    ...row,
    tagged: held.tagged ? { ...held.tagged, messageId: held.line?.id ?? null } : null,
    inMessages: theirs ? { messageId: theirs.id, jobKey: jobKeyOfRow(theirs) } : null,
    guess: held.tagged ? null : held.guess,
  }
}

/** Whether a row wants a guess: its conversation not tagged, the mail not folded, and no line of it on a job already. */
export function wantsGuess(row: Pick<MyMailRow, 'folded'>, held: { tagKey: string | null; line: MyMailLine | null }): boolean {
  return held.tagKey === null && row.folded === null && !(held.line && jobKeyOfRow(held.line))
}

/**
 * The guess's thread rule (punch list #263 PR C, call 5, v2.6747): the job a conversation is on already, by the page.
 * A mail's own conversation says the job outright when another mail of it, on the same page, is held by a line on a
 * job (`inMessages.jobKey`, or an earlier tag's line the person kept after an untag): that row read *already in
 * Messages ✓* while its newer reply read *Tag…*, and the guess never looked. One job per conversation; two different
 * jobs among its held lines say nothing, and the subject, party and domain steps are tried instead. Pure.
 */
export function conversationJobs(rows: readonly { threadId: string; jobKey: string | null }[]): Record<string, string> {
  const seen = new Map<string, string | null>()
  for (const r of rows) {
    if (!r.jobKey) continue
    const had = seen.get(r.threadId)
    if (had === undefined) seen.set(r.threadId, r.jobKey)
    else if (had !== null && had !== r.jobKey) seen.set(r.threadId, null)
  }
  const out: Record<string, string> = {}
  for (const [threadId, key] of seen) if (key) out[threadId] = key
  return out
}

/** Why the thread rule guessed: *a mail of this conversation is on JP1077 already*. */
export function conversationWhy(chip: Pick<MyMailJobChip, 'num' | 'name'>): string {
  return `a mail of this conversation is on ${chip.num.trim() || chip.name.trim() || 'this job'} already`
}

/**
 * The thread rule's guess for a row: the chip of the job its conversation is on already (`conversationJobs`), or null
 * when none is, or when the page did not load that chip. Tried before `guessJob`'s three steps.
 */
export function conversationGuess(threadId: string, onJob: Readonly<Record<string, string>>, chips: Readonly<Record<string, MyMailJobChip>>): MyMailGuess | null {
  const key = onJob[threadId]
  const chip = key ? chips[key] : undefined
  return chip ? { ...chip, why: conversationWhy(chip) } : null
}

// ---------- what a tag writes ----------

/** A line the tag found by its Message-ID, as `planTag` reads it. */
export interface MyMailHeldLine extends MyMailLine {
  rfc_message_id: string | null
  contact_id?: string | null
  mailbox?: string | null
}

/**
 * What a conversation's `email_tag_threads` row records of the lines its tag and its follow tied (`tied_line_ids`), the
 * job it put them on, and who it stamped as tying them (the row's `tagged_by`: the person whose press it was, or the
 * dev when the tag came through the dev seat, `myMailTaggedBy`). An untag unties these and no others, and a tag onto
 * another job moves them; a line someone placed by hand since is left where they put it.
 */
export interface MyMailTagRecord {
  tied: readonly string[]
  jobKey: string | null
  taggedBy: string | null
}

/** A tag row's record of its ties, or null when there is no row. A row read before the column was pushed records none. */
export function myMailTagRecord(row: { tied_line_ids?: readonly string[] | null; bid_id: string | null; project_id: string | null; jobs_ledger_id: string | null; tagged_by?: string | null } | null | undefined): MyMailTagRecord | null {
  if (!row) return null
  return { tied: [...new Set((row.tied_line_ids ?? []).filter((id) => typeof id === 'string' && id !== ''))], jobKey: jobKeyOfRow(row), taggedBy: row.tagged_by ?? null }
}

/** The record after more ties: the old ids first, each once. */
export function withTies(record: readonly string[] | null | undefined, more: readonly string[]): string[] {
  return [...new Set([...(record ?? []), ...more].filter((id) => typeof id === 'string' && id !== ''))]
}

/**
 * Whether a line is still the tag's own tie: recorded on its row, not the person's own, still on the job the tag put it
 * on, and last tied by whom the tag stamped (`tied_by`): the row's tagger, or the person whose box it is, since a
 * conversation the dev seat tagged for them (`tagged_by` the dev) may hold ties of their own press as well. A line
 * anyone else moved, untied or tied again by hand is theirs.
 */
export function isTagTie(line: Pick<MyMailLine, 'id' | 'bid_id' | 'project_id' | 'jobs_ledger_id' | 'mail_user_id' | 'tied_by'>, record: MyMailTagRecord | null, userId: string): boolean {
  if (!record || record.jobKey === null || !record.tied.includes(line.id)) return false
  if (line.mail_user_id === userId) return false
  const tiedBy = line.tied_by ?? null
  return jobKeyOfRow(line) === record.jobKey && (tiedBy === userId || (record.taggedBy !== null && tiedBy === record.taggedBy))
}

/**
 * Who a tag's row names as its tagger (`email_tag_threads.tagged_by`): whoever made this tag, the person on their own
 * press and the dev when it came through the dev seat (`actorId`), with the box staying the row's `user_id`. A second
 * tag onto the job the conversation is already on by a tag keeps the first tagger, as its grey line keeps its words; a
 * tag onto another job, or over a row the app placed by itself, is the new tagger's.
 */
export function myMailTaggedBy(actorId: string, jobKey: string, before: { record: MyMailTagRecord | null; placedByApp: boolean }): string {
  const first = before.record
  return first && !before.placedByApp && first.jobKey === jobKey && first.taggedBy ? first.taggedBy : actorId
}

/**
 * `planTag`'s `known.byMessageId`: each line by its Message-ID, `mine` when this person's own box wrote it, and
 * `tagTie` when the conversation's row records it as the tag's own tie and it is still where the tag put it.
 */
export function knownLines(lines: readonly MyMailHeldLine[], userId: string, record: MyMailTagRecord | null = null): Record<string, MyMailKnownLine> {
  const out: Record<string, MyMailKnownLine> = {}
  for (const l of lines) {
    const rfc = (l.rfc_message_id ?? '').trim()
    if (!rfc || out[rfc]) continue
    const mine = l.mail_user_id === userId && l.mailbox === MY_MAIL_MAILBOX
    out[rfc] = { messageId: l.id, jobKey: jobKeyOfRow(l), mine, ...(!mine && isTagTie(l, record, userId) ? { tagTie: true } : {}) }
  }
  return out
}

/**
 * `planTag`'s `known.byGmailId`: the person's own lines by the mail's Gmail id, for a mail with no Message-ID, as `list`
 * finds one. A Gmail id is one box's own, so only a line from this person's box counts.
 */
export function knownOwnLines(lines: readonly (MyMailLine & { gmail_id?: string | null; mailbox?: string | null })[], userId: string): Record<string, MyMailKnownLine> {
  const out: Record<string, MyMailKnownLine> = {}
  for (const l of lines) {
    const id = (l.gmail_id ?? '').trim()
    if (!id || out[id] || l.mail_user_id !== userId) continue
    out[id] = { messageId: l.id, jobKey: jobKeyOfRow(l), mine: true }
  }
  return out
}

/** The team's addresses for `planTag`'s `known.team`, as the bids@ reader gathers them (`gmail-sync`'s `loadTeam`). */
export function myMailTeam(users: readonly { id: string; name: string | null; email: string | null }[]): Record<string, { userId: string; name: string }> {
  const out: Record<string, { userId: string; name: string }> = {}
  for (const u of users) {
    const key = myMailAddressKey(u.email)
    if (key) out[key] = { userId: u.id, name: (u.name ?? '').trim() || key }
  }
  return out
}

type WriteStep = Extract<MyMailTagStep, { kind: 'write' }>

/**
 * The row `email_write_line` takes for a tagged mail, as `gmail-sync`'s `takeOne` builds one, column for column: the
 * invitation read off a mail in, the contact and the address it was placed on, the way, who wrote a mail out, who and
 * when, the subject and the words, the conversation, the box, the Message-ID and the job. The box is `mine` and the
 * person whose box it came from rides as `mail_user_id`.
 */
export function myMailLineRow(
  step: WriteStep,
  plan: Pick<MyMailTagPlan, 'mailbox' | 'mailUserId' | 'jobColumns'>,
  placed: { contactId: string; channelId: string | null },
  invitation: unknown = null,
): Record<string, unknown> {
  return {
    invitation,
    contact_id: placed.contactId,
    channel_id: placed.channelId,
    direction: step.direction,
    who_user_id: step.whoUserId,
    who_text: step.whoText,
    at: step.at,
    subject: step.subject,
    body: step.body,
    gmail_thread_id: step.threadId,
    mailbox: plan.mailbox,
    rfc_message_id: step.rfcMessageId,
    mail_user_id: plan.mailUserId,
    ...plan.jobColumns,
    // Filed for the record (v2.7027): `email_write_line` keeps the mark, and `messages_move_state` opens nothing for it.
    ...(step.history ? { history: true } : {}),
  }
}

/** The private bucket a tagged line's files and its raw copy go to, as the bids@ reader's files do. */
export const MY_MAIL_BUCKET = 'message-attachments'
/** The raw mail's type: the Legal desk's Evidence takes an email as `.eml` (`message/rfc822`). */
export const MY_MAIL_EML_MIME = 'message/rfc822'

/** A file's name as a path part, as the bids@ reader writes one: letters, digits, dots, dashes, underscores and spaces. */
export const safeFileName = (name: string): string => name.replace(/[^A-Za-z0-9._ -]+/g, '_').slice(0, 120) || 'file'

/**
 * Where a tagged mail's file is copied: under `mine/`, the person and the mail's Gmail id, as the reader's
 * `<gmail id>/<part>-<name>` but under the person, since a Gmail id is one box's own. `n` names a part with no id.
 */
export function myMailFilePath(userId: string, gmailId: string, partId: string, n: number, name: string): string {
  return `mine/${userId}/${gmailId}/${partId || n}-${safeFileName(name)}`
}

/** Where a tagged line's raw mail is kept as received: the court-ready copy the Legal desk's Evidence reads (PR 5). */
export const myMailEmlPath = (lineId: string): string => `mine/${lineId}.eml`

/**
 * A file row for `email_write_line`'s `p_files`, as `takeOne` writes one: a file host's link as a link; a file over 25 MB
 * left in Gmail as too big; a copied file at its path; one that would not copy left in Gmail as not copied.
 */
export function myMailFileRow(f: EmailFileRow, kept?: { path: string } | { left: 'not_copied' }): Record<string, unknown> {
  if (f.kind === 'link') return { kind: 'link', name: f.name, url: f.url, host: f.host }
  const base = { kind: 'file', name: f.name, mime: f.mime, size_bytes: f.size, gmail_attachment_id: f.attachmentId, paper: f.paper }
  if (f.keep === 'tooBig') return { ...base, left_in_gmail: 'too_big' }
  return kept && 'path' in kept ? { ...base, bucket_path: kept.path } : { ...base, left_in_gmail: 'not_copied' }
}

// ---------- the tag's grey line on the thread ----------

/** The key a tag's grey line stands on (`messages.quo_id`): one line per tagged conversation, by its `email_tag_threads` row. */
export const myMailTagEventKey = (tagRowId: string): string => `mytag:${tagRowId}`

/** A login as the grey line names one: the name, else the address. */
export interface MyMailNamed {
  name: string
  email: string
}

const namedAs = (who: MyMailNamed): string => who.name.trim() || who.email.trim()

/** What the grey line adds when every mail the tag wrote was filed for the record (v2.7027, punch list #324). */
export const MY_MAIL_FILED_WORDS = 'This is old mail, filed for the record. Nothing went on Follow up.'

/** Whether every mail a tag wrote was filed for the record: at least one line to write, and each of them old. */
export function tagAllFiled(counts: Pick<MyMailTagPlan['counts'], 'lines' | 'filed'>): boolean {
  return counts.lines > 0 && counts.filed === counts.lines
}

/**
 * The grey line's words: who tagged the conversation, and that later mail in it lands by itself. The name, else the
 * address. `who` is the person whose box the conversation is in. `seat` is the dev when the tag came through the dev
 * seat (`plan_mail_tag` → `apply_mail_tag`): the line then names the dev as the one who tagged, the person as the
 * mail's owner, and the seat as the way, so nobody reads the seat's work as the person's own press.
 */
export function myMailTagEventWords(who: MyMailNamed, seat?: MyMailNamed | null, filed = false): string {
  // Every mail the tag wrote was old (v2.7027, punch list #324): the line says so, and that nobody was asked.
  const later = `${filed ? `${MY_MAIL_FILED_WORDS} ` : ''}Later mail in it lands here by itself.`
  if (!seat) return `${namedAs(who)} tagged this conversation from their mail. ${later}`
  const own = seat.email.trim() !== '' && seat.email.trim().toLowerCase() === who.email.trim().toLowerCase()
  return `${namedAs(seat)} tagged this conversation from ${own ? 'their' : `${namedAs(who)}'s`} mail, through the dev seat. ${later}`
}

/**
 * The row of a tag's grey line in the other party's thread, the app's own event as `_shared/estimateThreadLine.ts`
 * writes one: `channel` event, `direction` team, `who_text` The app, keyed on `quo_id` by the tag's row so a second tag
 * writes none, and on the tag's job in its one column. Its time is the database's: when the tag was pressed.
 */
export function myMailTagEventRow(input: {
  tagRowId: string
  who: MyMailNamed
  contactId: string
  jobColumns: MyMailTagPlan['jobColumns']
  /** The app's own words when it placed the conversation from the person's Sent (punch list #263 PR B, `placedByAppWords`). */
  words?: string
  /** The dev whose seat the tag came through, when it did (`myMailTagEventWords`). */
  seat?: MyMailNamed | null
  /** Every mail the tag wrote was filed for the record (`tagAllFiled`): the words say so. */
  filed?: boolean
}): Record<string, unknown> {
  return {
    contact_id: input.contactId,
    channel: 'event',
    direction: 'team',
    who_text: 'The app',
    body: input.words?.trim() || myMailTagEventWords(input.who, input.seat, input.filed === true),
    quo_id: myMailTagEventKey(input.tagRowId),
    ...input.jobColumns,
  }
}

// ---------- what an untag removes ----------

/**
 * What an untag does. Every line the person's own box wrote for the conversation goes, with its files and its raw
 * copy, but for one the office keeps something on (`kept`: a promise written down on it, `message_promises`, or a
 * highlight, `message_highlights`, which would go with it), which stays with its files. A line the boxes wrote stays,
 * and is untied only when the conversation's row records it as the tag's own tie (`record`, `isTagTie`): never a line
 * the person or the office tied by hand, whoever tied it.
 */
export function planUntag(input: {
  userId: string
  record: MyMailTagRecord | null
  own: readonly Pick<MyMailLine, 'id'>[]
  kept?: readonly string[]
  /** The lines the record names, as read now. */
  tied?: readonly MyMailLine[]
}): { remove: string[]; keep: string[]; untie: string[] } {
  const kept = new Set(input.kept ?? [])
  const own = [...new Set(input.own.map((l) => l.id))]
  const remove = own.filter((id) => !kept.has(id))
  const keep = own.filter((id) => kept.has(id))
  const mine = new Set(own)
  const untie = (input.tied ?? []).filter((l) => !mine.has(l.id) && isTagTie(l, input.record, input.userId)).map((l) => l.id)
  return { remove, keep, untie: [...new Set(untie)] }
}

/** Postgres's unique violation (`23505`): a row the insert would double is already there, as `ON CONFLICT DO NOTHING` would leave it. */
export const isDuplicateKey = (code: string | null | undefined): boolean => code === '23505'

/**
 * The copies a write made that no line names, once `email_write_line` stood back on a line written first (another
 * reader's, another person's, or this person's own a moment ago): the paths uploaded, less every path a
 * `message_attachments` row holds. Those go, so the bucket keeps no file no line shows.
 */
export function orphanCopies(uploaded: readonly string[], named: readonly (string | null | undefined)[]): string[] {
  const held = new Set(named.filter((p): p is string => typeof p === 'string' && p !== ''))
  return [...new Set(uploaded.filter((p) => p !== '' && !held.has(p)))]
}

/**
 * A read that names a column a migration adds before the push has run: Postgres's undefined column (`42703`), or
 * PostgREST's own words for a column or a link it does not know (`PGRST200`, `PGRST204`), as the Legal desk's io reads
 * them. The untag counts a matter's copies of the lines this way (`legal_matter_documents.source_message_id`, PR 5), and
 * reads none until the column is there.
 */
export const columnNotPushed = (code: string | null | undefined): boolean => code === '42703' || code === 'PGRST200' || code === 'PGRST204'

// ---------- the follow: later mail in a tagged conversation (PR 4) ----------

/** The cron's request (`gmail-mine-follow`, every five minutes). The tab never sends it, and `parseMyMailRequest` refuses it. */
export interface MyMailFollowRequest {
  action: 'follow'
}

/** A run of the follow: the tagged conversations it read, the lines it wrote and tied, and how many it could not read. */
export interface MyMailFollowOk {
  ok: true
  rows: number
  lines: number
  tied: number
  failed: number
  /** Entries written onto HR files this run (punch list #289); a function deployed before it sends none. */
  entries?: number
}

/** Whether a body is the cron's `{ action: 'follow' }`. */
export function isFollowRequest(raw: unknown): raw is MyMailFollowRequest {
  return Boolean(raw) && typeof raw === 'object' && (raw as Record<string, unknown>).action === 'follow'
}

/** How many tagged conversations one run of the follow reads; the rest wait for the next run, five minutes on. */
export const FOLLOW_ROWS_PER_RUN = 100

/**
 * How long a tagged conversation is followed: until this many days since its newest mail (`last_mail_at`), or since
 * its tag when that is later, so a conversation is followed while it is alive and for this long after every tag.
 */
export const FOLLOW_WINDOW_DAYS = 60

/**
 * The office team's roles, as `gc_office_team()` names them (`src/lib/gc/access.ts`'s `GC_OFFICE_TEAM`, which the test
 * holds this to). The cron has no caller to ask the database's helper as, so the follow reads the roles itself.
 */
export const MY_MAIL_OFFICE_ROLES: readonly string[] = ['dev', 'master_technician', 'assistant', 'controller', 'estimator']

/** The start of the window: a conversation whose newest mail, or whose tag, is after this instant is followed. */
export function followSince(now: Date | number): string {
  const ms = typeof now === 'number' ? now : now.getTime()
  return new Date(ms - FOLLOW_WINDOW_DAYS * 86_400_000).toISOString()
}

/**
 * `greatest(last_mail_at, tagged_at) > since` as a PostgREST `or`: the rows the window holds, a conversation whose newest
 * mail or whose tag is younger than the window, however lately it was read. A tag holds its conversation for the whole
 * window even when its newest mail is older, since the tag's grey line says later mail lands by itself; a row with no
 * newest mail yet (tagged before the column was pushed, not read since) is held by its tag alone. The cron's gate
 * (`20261101172319_gmail_mine_follow_window.sql`) asks the same.
 */
export function followWindow(since: string): string {
  return `last_mail_at.gt.${since},tagged_at.gt.${since}`
}

/**
 * The newest mail of a conversation, which the follow's window keys on (`email_tag_threads.last_mail_at`): the latest
 * time Gmail took one of its mails (`internalDate`, the email's `at`), a draft, Spam, Trash and a chat left out as the
 * tag and the follow leave them. Never earlier than `kept`, the time the row already holds, so a mail deleted from
 * Gmail never pulls the window back. ISO; null when no mail has a time and nothing is kept.
 */
export function newestMailAt(messages: readonly Pick<EmailIn, 'at' | 'labels'>[], kept: string | null = null): string | null {
  const times = messages.flatMap((m) => (m.at && !neverRead(m.labels) ? [Date.parse(m.at)] : []))
  if (kept) times.push(Date.parse(kept))
  const newest = Math.max(...times.filter((ms) => Number.isFinite(ms)))
  return Number.isFinite(newest) ? new Date(newest).toISOString() : null
}

/** A person as the follow reads their `users` row. */
export interface MyMailFollowUserRow {
  id: string
  name: string | null
  email: string | null
  role: string | null
  read_only?: boolean | null
  is_sample?: boolean | null
  is_digital_twin?: boolean | null
  is_walk_tester?: boolean | null
  my_mail_on?: boolean | null
  archived_at?: string | null
  /** The labels they leave out, by name (`myMailHiddenLabels` reads them): the follow never copies a mail under one. */
  my_mail_hidden_labels?: unknown
  /** The Sent read's cursor (punch list #263 PR B): the newest sent mail read; null until the first run sets it. */
  my_mail_sent_read_at?: string | null
}

/** A person whose tagged conversations the follow reads, as that person: their id, their name and their own address. */
export interface MyMailFollowPerson {
  id: string
  name: string
  email: string
}

/**
 * Whose tagged conversations the follow reads, as the function's gate reads a person who may tag: their switch on
 * (`users.my_mail_on`), a real account (never a sample, a twin or the walk tester) that is not archived, on the office
 * team, not in training (a training account never tags, so its conversations wait), with an address of their own.
 */
export function followPeople(users: readonly MyMailFollowUserRow[]): MyMailFollowPerson[] {
  return users.flatMap((u) => {
    const email = (u.email ?? '').trim()
    const ok =
      u.my_mail_on === true &&
      !isFixtureAccount(u) &&
      u.is_walk_tester !== true &&
      !u.archived_at &&
      u.read_only !== true &&
      MY_MAIL_OFFICE_ROLES.includes(u.role ?? '') &&
      myMailAddressKey(email) !== ''
    return ok ? [{ id: u.id, name: (u.name ?? '').trim(), email }] : []
  })
}

/**
 * The job a tag's row names, as `planTag` takes it: a written line reads only its kind and id, so the chip's number and
 * name stay empty. Null when the row names none (its constraint says it always names one).
 */
export function tagRowJob(row: { bid_id: string | null; project_id: string | null; jobs_ledger_id: string | null }): MyMailJobChip | null {
  const key = jobKeyOfRow(row)
  const ref = jobRefOf(key)
  return key && ref ? { kind: ref.kind, id: ref.id, key, num: '', name: '' } : null
}

/** A line as the follow reads one: its job, whose box wrote it, who last tied it, and the two keys a mail finds it by. */
export interface MyMailFollowLine extends MyMailLine {
  gmail_id: string | null
  rfc_message_id: string | null
}

/**
 * What the follow does with one mail of a tagged conversation: read it whole and write it as the tag writes one
 * (`write`), tie a box's line that holds it to the tag's job (`tie`), leave the line that holds it where it is (`held`),
 * or leave it out (`skip`, with `planTag`'s reason).
 */
export type MyMailFollowStep =
  | { kind: 'write'; gmailId: string }
  | { kind: 'tie'; gmailId: string; messageId: string }
  | { kind: 'held'; gmailId: string; messageId: string }
  | { kind: 'skip'; gmailId: string; why: MyMailTagSkip }

/** Why a mail is never read or written, by its labels (the first of `MY_MAIL_NEVER_LABELS` it carries), or null. */
function neverWhy(labels: readonly string[]): MyMailTagSkip | null {
  for (const [label, why] of Object.entries(MY_MAIL_NEVER_LABELS)) if (labels.includes(label)) return why
  return null
}

/**
 * The follow's plan for one tagged conversation, read by its headers (`format=metadata`), over the lines that hold its
 * mail: by Message-ID in any box, else by Gmail id in this person's box, as `list` finds them. A draft, a mail in Spam
 * or Trash, a chat and a mail under a label the person leaves out (`known.hidden`, Gmail's ids) are left out, as a tag
 * leaves them. A mail a line holds is left where its line is, but for a box's line that sits on no job and that no
 * person has tied or untied (`tied_by` null), which is tied to the tag's job: the follow never moves a line a person
 * placed. Every other mail goes through `planTag` as the tag plans one, so a copy of ours (from a box or the app's
 * sender) and a Message-ID twice are left as the tag leaves them, never read whole run after run, and the rest are read
 * whole and written. In the conversation's order. Pure.
 */
export function planFollow(
  thread: MyMailThread,
  person: MyMailPerson,
  job: MyMailJobChip,
  known: { lines: readonly MyMailFollowLine[]; team?: MyMailKnown['team']; boxes?: MyMailKnown['boxes']; hidden?: MyMailKnown['hidden'] },
): MyMailFollowStep[] {
  const hidden = new Set(known.hidden ?? [])
  const leftOut = (labels: readonly string[]): MyMailTagSkip | null => neverWhy(labels) ?? (labels.some((l) => hidden.has(l)) ? 'hidden' : null)
  const byRfc = new Map<string, MyMailFollowLine>()
  const byId = new Map<string, MyMailFollowLine>()
  for (const l of known.lines) {
    const rfc = (l.rfc_message_id ?? '').trim()
    if (rfc && !byRfc.has(rfc)) byRfc.set(rfc, l)
    if (l.gmail_id && l.mail_user_id === person.userId && !byId.has(l.gmail_id)) byId.set(l.gmail_id, l)
  }
  const lineOf = new Map<string, MyMailFollowLine>()
  const free: EmailIn[] = []
  for (const email of thread.messages) {
    if (leftOut(email.labels)) continue
    const rfc = rfcMessageId(email)
    const line = rfc ? byRfc.get(rfc) : byId.get(email.gmailId)
    if (line) lineOf.set(email.gmailId, line)
    else free.push(email)
  }
  const planned = new Map(planTag({ threadId: thread.threadId, messages: free }, person, job, { byMessageId: {}, team: known.team, boxes: known.boxes }).steps.map((s) => [s.gmailId, s]))
  const seen = new Set<string>()
  return thread.messages.map((email): MyMailFollowStep => {
    const never = leftOut(email.labels)
    if (never) return { kind: 'skip', gmailId: email.gmailId, why: never }
    const line = lineOf.get(email.gmailId)
    if (!line) {
      const step = planned.get(email.gmailId)
      if (step?.kind === 'write') return { kind: 'write', gmailId: email.gmailId }
      return { kind: 'skip', gmailId: email.gmailId, why: step?.kind === 'skip' ? step.why : 'twice' }
    }
    if (seen.has(line.id)) return { kind: 'skip', gmailId: email.gmailId, why: 'twice' }
    seen.add(line.id)
    const loose = !line.mail_user_id && jobKeyOfRow(line) === null && !line.tied_by
    return loose ? { kind: 'tie', gmailId: email.gmailId, messageId: line.id } : { kind: 'held', gmailId: email.gmailId, messageId: line.id }
  })
}

/** A followed conversation's `last_error` when Gmail no longer has it in the person's box: deleted there, nothing more lands. */
export const MY_MAIL_FOLLOW_GONE = 'This conversation is gone from their Gmail. Later mail in it cannot land.'

// ---------- the Sent side with no press (punch list #263 PR B, call 2) ----------

/**
 * The Gmail search the follow's Sent read makes for one person: their Sent since the cursor (`after:` in epoch seconds,
 * the second the newest mail read was taken, so the read picks that mail up again and the lines' fences drop it),
 * never a draft, Spam, Trash or a chat, never a label the person leaves out. A mail already on a job is dropped by the
 * database's own fences (the conversation's row, the line's Message-ID), never by a label: a tag puts none on
 * (v2.7035). `myMailQuery` writes the hidden labels the same way.
 */
export function sentFollowQuery(since: string, hidden: readonly string[] = []): string {
  const epoch = Math.floor(Date.parse(since) / 1000)
  const parts = ['in:sent', `after:${Number.isFinite(epoch) ? epoch : 0}`, '-in:drafts', '-in:spam', '-in:trash', '-in:chats']
  const seen = new Set<string>()
  for (const name of hidden) {
    const label = name.replace(/"/g, '').replace(/\s+/g, ' ').trim()
    if (!label || seen.has(label.toLowerCase())) continue
    seen.add(label.toLowerCase())
    parts.push(`-label:"${label}"`)
  }
  return parts.join(' ')
}

/** How many sent mails one run reads for one person; the rest wait for the next run, five minutes on. */
export const SENT_FOLLOW_PAGE = 25

/**
 * Whether a sent mail is new to the cursor: taken at or after it (Gmail's `after:` is by the second, and the fake and
 * the real box may both answer the mail the cursor was set from; the lines' Message-ID fence drops it again). A mail
 * with no time is left to the lines' fences too.
 */
export function sentSince(email: Pick<EmailIn, 'at'>, since: string): boolean {
  const at = email.at ? Date.parse(email.at) : NaN
  const from = Date.parse(since)
  return !Number.isFinite(at) || !Number.isFinite(from) || at >= from
}

/**
 * The job a sent mail lands on, by the guess's steps 3 and 4 alone (`guessJob` with no subject jobs): the party's
 * address on exactly one open job (a starred one first), or its domain one customer's with exactly one open job. The
 * subject is never read for the Sent side: a number in a subject is a person's hint to the tab, not a fact to act on.
 */
export function sentPlacement(party: MyMailParty, facts: MyMailGuessFacts): MyMailGuess | null {
  return guessJob({ subject: MY_MAIL_NO_SUBJECT, who: party }, { ...facts, subjectJobs: [], taggedJob: null })
}

/** The grey line's words when the app placed a sent mail: who wrote to whom, where it went, why, and that later mail follows. */
export function placedByAppWords(person: { name: string; email: string }, party: MyMailParty, chip: Pick<MyMailJobChip, 'num' | 'name'>, why: string): string {
  const who = person.name.trim() || person.email.trim()
  const them = party.name.trim() || party.address.trim()
  const job = chip.num.trim() || chip.name.trim() || 'the job'
  return `The app put ${who}'s mail to ${them} on ${job}, since ${why.trim()}. Later mail in it lands here by itself.`
}

/** The small print on a line the app placed: *from Wendi's mail · put here by the app*. */
export function placedLineWords(name: string): string {
  return `from ${name.trim() || 'their'}${name.trim() ? "'s" : ''} mail · put here by the app`
}

/** The words of the untag's confirm on such a line, and its press. */
export const PLACED_LINE_WORDS = {
  untag: 'Untag',
  untagAsk: 'Take this conversation off the job? The lines the app put here go, with their files. The app will not put it back.',
  untagged: 'The conversation is off the job. The app will not put it back.',
  notUntagged: 'The conversation was not untagged.',
} as const

// ---------- telling a mailbox's owner that someone else saved their mail (v2.7068) ----------

export { MAIL_SAVED_CHANNEL, MAIL_SAVED_TEMPLATE } from './savedForYouNames.ts'
/** Saves this close together are one notice: a batch of seventeen reads as one line, not seventeen. */
export const MAIL_SAVED_BATCH_MINUTES = 30

/** What a batch of saves from one person's mail came to: who made them, how many conversations, onto how many jobs. */
export interface MailSavedFacts {
  savers: string[]
  conversations: number
  jobs: number
  /** The job in words, when every conversation went onto the same one. */
  job: string | null
}

/**
 * The facts of a batch, from the owner's `email_tag_threads` rows tagged since the batch began: only rows someone else
 * tagged onto a job (`tagged_by` not the owner, never an HR file's row), each saver by name once in the order they
 * first saved. `oneJob` is the job in words for the caller's own save, used when the whole batch went onto it.
 */
export function mailSavedFacts(
  rows: readonly { tagged_by?: string | null; bid_id: string | null; project_id: string | null; jobs_ledger_id: string | null; person_id?: string | null }[],
  ownerId: string,
  names: Readonly<Record<string, string>>,
  oneJob: { key: string; words: string } | null,
): MailSavedFacts {
  const theirs = rows.filter((r) => !r.person_id && r.tagged_by && r.tagged_by !== ownerId && jobKeyOfRow(r) !== null)
  const savers = [...new Set(theirs.map((r) => (names[r.tagged_by as string] ?? '').trim()).filter(Boolean))]
  const keys = [...new Set(theirs.map((r) => jobKeyOfRow(r) as string))]
  return { savers, conversations: theirs.length, jobs: keys.length, job: keys.length === 1 && oneJob && keys[0] === oneJob.key ? oneJob.words.trim() || null : null }
}

/** The notice's one line: who saved how many conversations from the owner's mail, and onto what. */
export function mailSavedTitle(facts: MailSavedFacts): string {
  const who = facts.savers.length === 0 ? 'A developer' : facts.savers.length === 1 ? facts.savers[0]! : `${facts.savers.slice(0, -1).join(', ')} and ${facts.savers[facts.savers.length - 1]}`
  const what = facts.conversations === 1 ? 'a conversation' : `${facts.conversations} conversations`
  const where = facts.jobs === 1 ? (facts.job ?? 'a job') : `${facts.jobs} jobs`
  return `${who} saved ${what} from your mail to ${where}.`
}

/** The notice's second line: how it was done, where the mail is now, and that the mailbox was not changed. */
export const MAIL_SAVED_BODY = 'They did it for you, through the dev seat. The mail is on the job in Messages, where the office reads it. Nothing changed in your Gmail.'

/** When the batch a notice belongs to began: `MAIL_SAVED_BATCH_MINUTES` back from now, as an ISO time. */
export function mailSavedBatchSince(now: string): string {
  return new Date(Date.parse(now) - MAIL_SAVED_BATCH_MINUTES * 60_000).toISOString()
}

// ---------- the old Gmail label, taken out of every mailbox once (v2.7035) ----------

/** Where the clean-up keeps its place: one `app_settings` row, so it needs no column of its own and ends by itself. */
export const LABEL_CLEANUP_KEY = 'my_mail_label_cleanup_v1'
/** How many mailboxes one run of the follow looks in: the rest wait for the next run, five minutes on. */
export const LABEL_CLEANUP_PER_RUN = 10
/** How many times a mailbox Google will not open is asked before the clean-up leaves it, counted as failed. */
export const LABEL_CLEANUP_TRIES = 3

/** What the clean-up found in one mailbox: no such label, the label deleted, or Google's refusal. */
export type LabelCleanupOutcome = 'none' | 'deleted' | 'failed'

export interface LabelCleanupMark {
  at: string
  outcome: LabelCleanupOutcome
  tries: number
  /** Google's reason for a failure, with every address taken out. */
  reason?: string
}

/** The clean-up's record: each mailbox by its login's id, and when every one was settled. */
export interface LabelCleanupState {
  boxes: Record<string, LabelCleanupMark>
  finished_at: string | null
}

/** The record as kept in `app_settings.value_text`; anything unreadable is a clean start. */
export function readLabelCleanup(valueText: string | null | undefined): LabelCleanupState {
  try {
    const raw = valueText ? (JSON.parse(valueText) as Partial<LabelCleanupState> | null) : null
    const boxes: Record<string, LabelCleanupMark> = {}
    for (const [id, m] of Object.entries(raw?.boxes ?? {})) {
      const outcome = (['none', 'deleted', 'failed'] as const).find((o) => o === m?.outcome)
      if (outcome && typeof m.at === 'string') boxes[id] = { at: m.at, outcome, tries: Number.isFinite(m.tries) ? Number(m.tries) : 1, ...(typeof m.reason === 'string' ? { reason: m.reason } : {}) }
    }
    return { boxes, finished_at: typeof raw?.finished_at === 'string' ? raw.finished_at : null }
  } catch {
    return { boxes: {}, finished_at: null }
  }
}

/** Whether a mailbox is settled: looked in with an answer, or refused by Google as often as the clean-up asks. */
const labelSettled = (m: LabelCleanupMark | undefined): boolean => Boolean(m) && (m!.outcome !== 'failed' || m!.tries >= LABEL_CLEANUP_TRIES)

/** The mailboxes still to look in, one never asked before one that failed, at most a run's worth. */
export function labelCleanupDue(state: LabelCleanupState, userIds: readonly string[]): string[] {
  const due = [...new Set(userIds)].filter((id) => !labelSettled(state.boxes[id]))
  return due.sort((a, b) => (state.boxes[a]?.tries ?? 0) - (state.boxes[b]?.tries ?? 0)).slice(0, LABEL_CLEANUP_PER_RUN)
}

/** The record after one mailbox was looked in. A failure counts its tries; an answer settles it. */
export function labelCleanupMarked(state: LabelCleanupState, userId: string, result: { outcome: LabelCleanupOutcome; reason?: string }, now: string): LabelCleanupState {
  const tries = (state.boxes[userId]?.tries ?? 0) + 1
  const reason = result.outcome === 'failed' && result.reason ? { reason: labelCleanupReason(result.reason) } : {}
  return { ...state, boxes: { ...state.boxes, [userId]: { at: now, outcome: result.outcome, tries, ...reason } } }
}

/** Google's reason as the record and the log keep it: one line, every address out, 160 characters at most. */
export function labelCleanupReason(words: string): string {
  return words.replace(/[^\s<>"'()]+@[^\s<>"'()]+/g, '(an address)').replace(/\s+/g, ' ').trim().slice(0, 160)
}

/** The clean-up's counts over the mailboxes it covers: how many, looked in, with the label deleted, with none, failed, and left. */
export function labelCleanupCounts(state: LabelCleanupState, userIds: readonly string[]): { mailboxes: number; checked: number; deleted: number; none: number; failed: number; left: number } {
  const ids = [...new Set(userIds)]
  const marks = ids.map((id) => state.boxes[id])
  const of = (o: LabelCleanupOutcome) => marks.filter((m) => m?.outcome === o).length
  return { mailboxes: ids.length, checked: marks.filter(Boolean).length, deleted: of('deleted'), none: of('none'), failed: of('failed'), left: ids.filter((id) => !labelSettled(state.boxes[id])).length }
}

/** Gmail's id of the old label in a box's labels, by its exact name, or null when the box has none. */
export function oldLabelId(labels: readonly { id: string; name: string }[] | undefined): string | null {
  return (labels ?? []).find((l) => l.name === MY_MAIL_GMAIL_LABEL)?.id ?? null
}

/**
 * Whether an address is one the delegation reaches: on the Workspace's own domain (the domain of the box the reader
 * signs in as). With no domain known every address is tried, and Google refuses the ones it does not hold.
 */
export function onWorkspace(email: string | null | undefined, domain: string | null | undefined): boolean {
  const key = myMailAddressKey(email)
  if (!key) return false
  const d = (domain ?? '').trim().toLowerCase()
  return d === '' || key.endsWith(`@${d}`)
}

// ---------- the seat's dry run (server 0.30.0) ----------

/** Why a mail is never written, in words the seat reads back. */
export const MY_MAIL_SKIP_WORDS: Readonly<Record<MyMailTagSkip, string>> = {
  draft: 'a draft',
  spamOrTrash: 'in spam or the trash',
  chat: 'a chat',
  hidden: 'under a label the person leaves out',
  noParty: 'nobody outside to land it on',
  twice: 'the same mail twice in the conversation',
}

/**
 * The plan of a tag as the dev seat reads it back before anything is written (`plan_mail_tag`): the job, the counts,
 * each mail with what the tag would do to it and the headers that say which mail it is, and the job the conversation
 * was on before when a tag would move it. Pure: the function hands in the plan it would execute and the mails it read.
 */
export function tagPlanPreview(plan: MyMailTagPlan, emails: readonly EmailIn[], account: string, movingFrom: string | null): MyMailTagPlanOk {
  const byId = new Map(emails.map((e) => [e.gmailId, e]))
  const mails: MyMailTagPlanMail[] = plan.steps.map((s) => {
    const e = byId.get(s.gmailId)
    const head = { gmailId: s.gmailId, at: e?.at ?? null, from: e?.from ? (e.from.name?.trim() ? `${e.from.name.trim()} <${e.from.address}>` : e.from.address) : '', subject: e?.subject ?? '' }
    if (s.kind === 'skip') return { ...head, kind: 'skip', why: MY_MAIL_SKIP_WORDS[s.why] }
    if (s.kind === 'tie') return { ...head, kind: 'tie', tie: s.tie, why: s.tie ? (s.onJob ? `a line on ${s.onJob} moves onto this job` : 'a line on the person is tied to this job') : s.onJob === plan.jobKey ? 'already on this job' : `the office’s tie on ${s.onJob ?? 'nothing'} stays` }
    return { ...head, kind: 'write', files: s.files.length, lands: s.history ? 'record' : 'followUp' }
  })
  return { ok: true, plan: true, threadId: plan.threadId, account, job: plan.job, counts: plan.counts, mails, movingFrom }
}

/**
 * The plan of a person tag as the seat reads it back (punch list #289): the person, whether the conversation is followed
 * onto the file already, the counts, and each mail with what the tag would do — a new entry on its day with its files
 * counted, one the file holds already, or a skip with why. A `stop` plan lists no mail: `counts.already` is what the file
 * holds for the conversation and `following` says whether there is a follow to lift. Pure.
 */
export function personTagPlanPreview(
  plan: MyMailPersonTagPlan,
  emails: readonly Pick<EmailIn, 'gmailId' | 'at' | 'from' | 'subject'>[],
  input: { account: string; person: { id: string; name: string }; following: boolean; stop: boolean },
): MyMailPersonTagPlanOk {
  const byId = new Map(emails.map((e) => [e.gmailId, e]))
  const mails: MyMailPersonTagPlanMail[] = input.stop
    ? []
    : plan.steps.map((s) => {
        const e = byId.get(s.gmailId)
        const head = { gmailId: s.gmailId, at: e?.at ?? null, from: e?.from ? (e.from.name?.trim() ? `${e.from.name.trim()} <${e.from.address}>` : e.from.address) : '', subject: e?.subject ?? '' }
        if (s.kind === 'skip') return { ...head, kind: 'skip', why: MY_MAIL_SKIP_WORDS[s.why] }
        if (s.kind === 'already') return { ...head, kind: 'already', why: 'an entry on the file holds this mail' }
        return { ...head, kind: 'entry', entryDate: s.entryDate, files: s.files }
      })
  const counts = input.stop ? { entries: 0, already: plan.counts.already, skipped: 0 } : plan.counts
  return { ok: true, plan: true, threadId: plan.threadId, account: input.account, person: input.person, following: input.following, stop: input.stop, counts, mails }
}
